import{_ as t,c as e,o as c,ah as a}from"./chunks/framework.MgE-7MWY.js";const u=JSON.parse('{"title":"SENTINEZ - API SERVER","description":"","frontmatter":{},"headers":[],"relativePath":"vi/api-server.md","filePath":"vi/api-server.md"}'),i={name:"vi/api-server.md"};function r(h,n,o,l,d,g){return c(),e("div",null,[...n[0]||(n[0]=[a('<h1 id="sentinez-api-server" tabindex="-1">SENTINEZ - API SERVER <a class="header-anchor" href="#sentinez-api-server" aria-label="Permalink to “SENTINEZ - API SERVER”">​</a></h1><p>Tài liệu kỹ thuật cho máy chủ API của dự án <strong>Sentinez</strong> đây đóng vai trò là backend cho toàn bộ hệ thống.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Ban đầu, tất cả các dịch vụ thuộc <code>internal/core/*</code> đều được nhúng trực tiếp vào <code>apiserver</code>, và coi chúng như là một hệ thống monolithic truyền thống. Khi cần mở rộng hệ thống, ta có thể dễ dàng tách các dịch vụ trong <code>core</code> ra thành 1 microservice với <code>apiserver</code> đóng vai trò là API Gateway, gọi các dịch vụ trong <code>core</code> bằng giao thức gRPC</p></div><h2 id="_1-đac-ta" tabindex="-1">1. Đặc tả <a class="header-anchor" href="#_1-đac-ta" aria-label="Permalink to “1. Đặc tả”">​</a></h2><p><em>Sentinez</em> là dự án được triển khai hoàn toàn trên môi trường đám mây, việc thiết kế hệ thống Backend phải đáp ứng được những yêu cầu sau:</p><ul><li>Ứng dụng dễ dàng triển khai trên bất kì cloud plaform nào.</li><li>Ứng dụng phải nhẹ và linh hoạt, thời gian phát triển nhanh để đáp ứng được nhu cầu cấp bách của thị trường.</li><li>Ứng dụng phải chịu được tải lớn và dễ dàng mở rộng cả chiều rộng lẫn chiều sâu.</li></ul><p><em>API Server</em> như là trái tim của dự án. Server phải đủ sức mạnh để xử lý lượng lớn yêu cầu của người dùng.</p><h2 id="_2-yeu-cau-ky-thuat" tabindex="-1">2. Yêu cầu kỹ thuật <a class="header-anchor" href="#_2-yeu-cau-ky-thuat" aria-label="Permalink to “2. Yêu cầu kỹ thuật”">​</a></h2><p>Những kỹ năng bắt buộc phải có</p><ul><li>Ngôn ngữ lập trình Go</li><li>Protocol Buffer</li><li>Kỹ năng về GRPC Gateway, GRPC Service</li><li>PostgreSQL, Docker, REST API</li></ul>',10)])])}const p=t(i,[["render",r]]);export{u as __pageData,p as default};
